// TypeScript Version: 4.1

/**
* Interface describing `drssors`.
*/
interface Routine {
	/**
	* Computes the residual sum of squares of two double-precision floating-point strided arrays, ignoring `NaN` values and using ordinary recursive summation.
	*
	* @param N - number of indexed elements
	* @param x - first input array
	* @param strideX - stride length of `x`
	* @param y - second input array
	* @param strideY - stride length of `y`
	* @returns residual sum of squares
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var x = new Float64Array( [ 1.0, 2.0, 2.0, -7.0, -2.0, 3.0, 4.0, 2.0 ] );
	* var y = new Float64Array( [ 2.0, 1.0, 2.0, 1.0, -2.0, 2.0, 3.0, 4.0 ] );
	*
	* var z = drssors( x.length, x, 1, y, 1 );
	* // returns 72
	*/
	( N: number, x: Float64Array, strideX: number, y: Float64Array, strideY: number ): number;

	/**
	* Computes the residual sum of squares of two double-precision floating-point strided arrays, ignoring `NaN` values and using ordinary recursive summation and alternative indexing semantics.
	*
	* @param N - number of indexed elements
	* @param x - first input array
	* @param strideX - stride length of `x`
	* @param offsetX - starting index of `x`
	* @param y - second input array
	* @param strideY - stride length of `y`
	* @param offsetY - starting index of `y`
	* @returns residual sum of squares
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var x = new Float64Array( [ 1.0, 2.0, 2.0, -7.0, -2.0, 3.0, 4.0, 2.0 ] );
	* var y = new Float64Array( [ 2.0, 1.0, 2.0, 1.0, -2.0, 2.0, 3.0, 4.0 ] );
	*
	* var z = drssors.ndarray( x.length, x, 1, 0, y, 1, 0 );
	* // returns 72
	*/
	ndarray( N: number, x: Float64Array, strideX: number, offsetX: number, y: Float64Array, strideY: number, offsetY: number ): number;
}

/**
* Compute the residual sum of squares of two double-precision floating-point strided arrays, ignoring `NaN` values and using ordinary recursive summation.
*
* @param N - number of indexed elements
* @param x - first input array
* @param strideX - stride length of `x`
* @param y - second input array
* @param strideY - stride length of `y`
* @returns residual sum of squares
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var drssors = require( '@stdlib/blas/ext/base/drssors' );
*
* var x = new Float64Array( [ 1.0, -2.0, 2.0 ] );
* var y = new Float64Array( [ 1.0, 1.0, -4.0 ] );
*
* var out = drssors( x.length, x, 1, y, 1 );
* // returns 45
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var drssors = require( '@stdlib/blas/ext/base/drssors' );
*
* var x = new Float64Array( [ 1.0, 2.0, 2.0, -7.0, -2.0, 3.0, 4.0, 2.0 ] );
* var y = new Float64Array( [ 2.0, 1.0, 2.0, 1.0, -2.0, 2.0, 3.0, 4.0 ] );
*
* var z = drssors.ndarray( x.length, x, 1, 0, y, 1, 0 );
* // returns 72
*/
declare var drssors: Routine;


// EXPORTS //

export = drssors;
